"""Print the task board from the files under tasks/ (T-054).

    python scripts/board.py             # the open work, as a Markdown table
    python scripts/board.py --check     # list task files that are malformed
    python scripts/board.py --next      # the next free task number

The board is never edited by hand and is not a file that pull requests touch.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import task_files  # noqa: E402

BANNER = (
    "# Task board\n\n"
    "Generated by `python scripts/board.py` from the files in `tasks/`; do not edit. "
    "Open and in-progress work only: finished tasks are in `tasks/done/`.\n\n"
)


def next_free(tasks) -> str:
    numbers = [int(t.id[2:5]) for t in tasks if t.id]
    return "T-%03d" % (max(numbers, default=0) + 1)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="list malformed files and exit")
    parser.add_argument("--next", action="store_true", help="print the next free task number")
    parser.add_argument("--markdown", action="store_true", help="include the page heading")
    args = parser.parse_args(argv)
    tasks = task_files.load()
    if args.check:
        found = task_files.problems(tasks)
        for line in found:
            print(line)
        return 1 if found else 0
    if args.next:
        print(next_free(tasks))
        return 0
    sys.stdout.write((BANNER if args.markdown else "") + task_files.build_board(tasks))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
